window.rsDemoAsset=function(path){return (window.RS_DEMO_ASSETS&&window.RS_DEMO_ASSETS[path])||path;};
(function(){
  function fixImg(img){
    if(!img||!img.getAttribute)return;
    const raw=img.getAttribute('src');
    if(raw&&window.RS_DEMO_ASSETS&&window.RS_DEMO_ASSETS[raw]) img.setAttribute('src',window.RS_DEMO_ASSETS[raw]);
  }
  function scan(root){
    if(root&&root.matches&&root.matches('img')) fixImg(root);
    if(root&&root.querySelectorAll) root.querySelectorAll('img').forEach(fixImg);
  }
  document.addEventListener('DOMContentLoaded',()=>scan(document));
  const mo=new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(scan)));
  document.addEventListener('DOMContentLoaded',()=>mo.observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['src']}));
})();